design_text:
{
  "site_summary": "A bright shaded balcony with consistently moist soil, shared with one curious dog who loves to chew on plants.",
  "layout_strategy": "The scheme is structured in three vertical layers with trailing shade-loving ferns hanging from the upper balcony ceiling, lush upright architectural foliage in mid-level wall-mounted containers, and a dedicated pet-accessible ground tray positioned safely on the floor.",
  "combination_logic": "The combination relies on contrasting fine delicate fern fronds against broad glossy hosta leaves and soft tufted grasses, creating a rich tapestry of green textures that thrive in indirect light with consistent moisture, maintaining a vibrant jungle feel throughout spring, summer, and autumn.",
  "zones": [
    {
      "zone_name": "Canopy Hanging Layer",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "Suspended from ceiling hooks near the bright shaded balcony wall, receiving high indirect ambient light out of dog reach.",
      "plants": [
        {
          "scientific_name": "Nephrolepis exaltata",
          "common_name": "Boston Fern",
          "why": "Thrives in high moisture and bright indirect light without needing direct sun.",
          "role_in_combination": "Provides soft, cascading fine-textured green fronds that draw the eye upward and frame the view."
        }
      ],
      "maintenance": [
        "Water thoroughly twice a week as hanging baskets dry out faster.",
        "Mist fronds weekly to maintain high humidity.",
        "Prune away any brown or dead fronds in early spring.",
        "Repot into a slightly larger basket every two years."
      ]
    },
    {
      "zone_name": "Mid-Level Foliage Wall",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "Wall-mounted planters at waist height against the inner bright shaded balcony wall, receiving filtered indirect light.",
      "plants": [
        {
          "scientific_name": "Hosta plantaginea",
          "common_name": "Fragrant Plantain Lily",
          "why": "Loves shade and moist soil, producing lush foliage and evening-scented white flowers.",
          "role_in_combination": "Contributes broad, glossy, rounded leaves that offer a dramatic textural contrast against the fine fern fronds above."
        },
        {
          "scientific_name": "Calathea makoyana",
          "common_name": "Peacock Plant",
          "why": "Prefers bright indirect light and high moisture environments.",
          "role_in_combination": "Introduces intricate purple and green patterns on the undersides of leaves, adding a subtle color variation to the green-dominant palette."
        }
      ],
      "maintenance": [
        "Keep soil consistently moist but never waterlogged, checking moisture weekly.",
        "Feed with a balanced liquid fertilizer monthly during the growing season.",
        "Wipe broad leaves with a damp cloth bi-weekly to remove dust.",
        "Divide overcrowded Hosta clumps in early spring."
      ]
    },
    {
      "zone_name": "Pet Grazing Floor Patch",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "Placed flat on the balcony floor in a shaded corner, easily reachable by the household dog.",
      "plants": [
        {
          "scientific_name": "Dactylis glomerata",
          "common_name": "Pet-Safe Cat Grass / Orchard Grass Tray",
          "why": "Fast-growing, entirely non-toxic grass that satisfies the dog's urge to chew safely.",
          "role_in_combination": "Creates a soft, tufted vertical grassy texture at floor level that anchors the base of the design."
        }
      ],
      "maintenance": [
        "Water lightly every few days to keep the shallow tray moist.",
        "Trim the grass back when it gets too leggy to encourage fresh growth.",
        "Discard and re-seed the tray every 4 to 6 weeks as grasses naturally exhaust themselves."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers with a finger test",
      "frequency": "Twice a week in summer, weekly in spring and autumn",
      "season": "Summer and Spring"
    },
    {
      "task": "Apply organic liquid fertilizer to the mid-layer containers to support lush foliage growth",
      "frequency": "Monthly",
      "season": "Spring and Summer"
    },
    {
      "task": "Inspect hanging baskets and mid-level planters for fungal gnats or pests thriving in the high moisture",
      "frequency": "Bi-weekly",
      "season": "All seasons"
    }
  ],
  "care_cautions": [
    "Overwatering and root rot can occur in the hanging Boston Fern basket if excess water is trapped in the outer cache pot without proper drainage.",
    "The Calathea makoyana in the mid-layer is sensitive to cold drafts and sudden drops in temperature during autumn evenings.",
    "The dog may excessively dig up or destroy the ground-level grass tray if it is not firmly weighted down in its container."
  ],
  "pet_safety_note": "All plants chosen for this design are non-toxic, and the ground-level grass tray provides a designated safe space for the dog to chew without disturbing the mid and upper decorative displays."
}
